# lending-desk

The lending desk service of the city library's branches: checkouts, returns, renewals, holds, fees,
notices to members, and the self-check machines.

Plain Node.js ES modules, no dependencies. Node.js 22 or later.

```sh
npm test    # runs every test in test/
npm start   # serves the API on port 8080, with demo data
```
{
  "name": "lending-desk",
  "version": "0.4.0",
  "private": true,
  "type": "module",
  "description": "The lending desk service of the city library: checkouts, returns, renewals, holds, fees and notices.",
  "scripts": {
    "start": "node lib/server/http.js",
    "test": "node --test"
  }
}
import { normaliseBarcode } from '../catalog/barcodes.js';
import { isLendable } from '../catalog/items.js';
import { branchById } from '../config/branches.js';
import { canBorrow } from '../members/eligibility.js';
import { computeDueDate } from './due-dates.js';

/** Lends an item to a member. Returns { ok: true, loan } or { ok: false, reason }. */
export function checkOutItem(store, { barcode, memberId, today }) {
  const item = store.findItemByBarcode(normaliseBarcode(barcode));
  if (item === undefined) return { ok: false, reason: 'unknown-item' };
  const member = store.getMember(memberId);
  if (member === undefined) return { ok: false, reason: 'unknown-member' };
  if (!isLendable(item)) return { ok: false, reason: 'not-lendable' };
  if (store.findOpenLoan(item.id) !== undefined) return { ok: false, reason: 'on-loan' };
  if (findBlockingHold(store, item.id, member.id) !== null) return { ok: false, reason: 'on-hold' };
  const eligibility = canBorrow(store, member, today);
  if (!eligibility.ok) return eligibility;
  const loan = store.saveLoan({
    itemId: item.id,
    memberId: member.id,
    checkedOutOn: today,
    dueOn: computeDueDate({ checkedOutOn: today, format: item.format, branch: branchById(item.branchId) }),
    renewals: 0,
    returnedOn: null,
  });
  for (const hold of store.listHolds(item.id)) {
    if (hold.memberId === member.id && hold.status !== 'expired') {
      store.saveHold({ ...hold, status: 'collected' });
    }
  }
  return { ok: true, loan };
}

/** Returns the hold of another member that keeps an item from being lent, or null when none does. */
export function findBlockingHold(store, itemId, memberId) {
  const active = store
    .listHolds(itemId)
    .filter((hold) => hold.status === 'waiting' || hold.status === 'ready');
  return active.find((hold) => hold.memberId !== memberId) ?? null;
}
export { checkOutItem, findBlockingHold } from './checkout.js';
export { computeDueDate } from './due-dates.js';
export { renewLoan } from './renewals.js';
export { returnItem } from './returns.js';
/** Tells whether an item may leave the library on loan: it is in service, not missing or withdrawn. */
export function isLendable(item) {
  return item.status === 'in-service';
}

/** Describes an item for a librarian, such as "The Hobbit (book)". */
export function describeItem(item) {
  return `${item.title} (${item.format})`;
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { checkOutItem } from '../lib/circulation/checkout.js';
import { ADA, BEN, BOOK, sampleLoan, sampleStore, TODAY } from './sample-library.js';

test('lends an item and gives the loan its due date', () => {
  const store = sampleStore();
  const result = checkOutItem(store, { barcode: BOOK.barcode, memberId: ADA.id, today: TODAY });
  assert.equal(result.ok, true);
  assert.equal(result.loan.dueOn, '2026-12-17');
  assert.equal(store.findOpenLoan(BOOK.id).memberId, ADA.id);
});

test('reads a barcode with spaces and dashes in it', () => {
  const result = checkOutItem(sampleStore(), {
    barcode: '3123-4000 0000 16',
    memberId: ADA.id,
    today: TODAY,
  });
  assert.equal(result.ok, true);
});

test('refuses an item that is already on loan', () => {
  const loan = sampleLoan({
    id: 'loan_9',
    item: BOOK,
    member: BEN,
    checkedOutOn: '2026-11-20',
    dueOn: '2026-12-11',
  });
  const result = checkOutItem(sampleStore({ loans: [loan] }), {
    barcode: BOOK.barcode,
    memberId: ADA.id,
    today: TODAY,
  });
  assert.deepEqual(result, { ok: false, reason: 'on-loan' });
});

test('refuses an item that is held for another member', () => {
  const hold = {
    id: 'hold_1',
    itemId: BOOK.id,
    memberId: BEN.id,
    pickupBranchId: 'central',
    placedOn: '2026-11-01',
    status: 'ready',
    readyOn: '2026-11-25',
  };
  const result = checkOutItem(sampleStore({ holds: [hold] }), {
    barcode: BOOK.barcode,
    memberId: ADA.id,
    today: TODAY,
  });
  assert.deepEqual(result, { ok: false, reason: 'on-hold' });
});

test('lends a held item to the member who holds it, and marks the hold collected', () => {
  const hold = {
    id: 'hold_1',
    itemId: BOOK.id,
    memberId: ADA.id,
    pickupBranchId: 'central',
    placedOn: '2026-11-01',
    status: 'ready',
    readyOn: '2026-11-25',
  };
  const store = sampleStore({ holds: [hold] });
  const result = checkOutItem(store, { barcode: BOOK.barcode, memberId: ADA.id, today: TODAY });
  assert.equal(result.ok, true);
  assert.equal(store.listHolds(BOOK.id)[0].status, 'collected');
});

test('refuses an item that is withdrawn', () => {
  const withdrawn = { ...BOOK, id: 'itm_old', barcode: '31234000000057', status: 'withdrawn' };
  const store = sampleStore({ items: [withdrawn] });
  const result = checkOutItem(store, { barcode: withdrawn.barcode, memberId: ADA.id, today: TODAY });
  assert.deepEqual(result, { ok: false, reason: 'not-lendable' });
});
